package fr.cercle.tourderole;
import android.app.*;import android.widget.*;import org.json.*;import java.util.*;
public final class Investigations{
static JSONArray cases(MainActivity a){return a.cfg.optJSONArray("cases");}
public static void seed(MainActivity a)throws Exception{JSONArray all=cases(a);if(all==null)return;for(int i=0;i<all.length();i++){JSONObject c=all.optJSONObject(i);boolean found=false;for(int j=0;j<a.rows("affaires").length();j++)if(a.rows("affaires").optJSONObject(j).optString("_case").equals(c.optString("id")))found=true;if(!found){JSONObject r=a.insert("affaires",c.optString("title"));r.put("_case",c.optString("id"));r.put("notes","");}}a.save();}
static JSONObject source(MainActivity a,JSONObject r){JSONArray all=cases(a);for(int i=0;i<all.length();i++)if(all.optJSONObject(i).optString("id").equals(r.optString("_case")))return all.optJSONObject(i);return null;}
static HashSet<Integer> indices(JSONObject r,String key){HashSet<Integer> out=new HashSet<>();JSONArray arr=r.optJSONArray(key);if(arr!=null)for(int i=0;i<arr.length();i++)out.add(arr.optInt(i));return out;}
static void put(JSONObject r,String key,Set<Integer> ids)throws Exception{JSONArray out=new JSONArray();ArrayList<Integer> sorted=new ArrayList<>(ids);Collections.sort(sorted);for(int n:sorted)out.put(n);r.put(key,out);}
public static void actions(MainActivity a){if(a.current.equals("affaires"))a.root.addView(a.text("Deux enquêtes originales. Consulte les pièces, recoupe les horaires, puis propose un verdict.",15,a.muted));}
public static void detail(MainActivity a,LinearLayout body,String tab,JSONObject r){if(!tab.equals("affaires")||!r.has("_case"))return;JSONObject c=source(a,r);if(c==null)return;body.addView(a.text(c.optString("intro"),18,a.paper));JSONArray docs=c.optJSONArray("docs");HashSet<Integer> read=indices(r,"_read"),pins=indices(r,"_pins");body.addView(a.text(read.size()+" / "+docs.length()+" pièces consultées · "+pins.size()+" épinglées",16,a.accent));for(int i=0;i<docs.length();i++){int n=i;JSONArray d=docs.optJSONArray(i);a.addButton(body,(read.contains(i)?"✓ ":"")+(pins.contains(i)?"★ ":"")+d.optString(0),()->a.attempt(()->document(a,r,c,n)));}a.addButton(body,"Mes indices épinglés",()->{StringBuilder text=new StringBuilder();for(int n:pins)text.append(docs.optJSONArray(n).optString(0)).append("\n\n").append(docs.optJSONArray(n).optString(1)).append("\n\n");a.info("Indices épinglés",text.length()==0?"Ouvre une pièce et choisis Épingler.":text.toString());});a.addButton(body,"Carnet de cette affaire",()->{a.current="carnet";a.filterKey="affaire";a.filterValue=r.optString("id");a.query="";a.home();});if(r.optBoolean("_solved"))a.addButton(body,"Relire la résolution",()->a.info("Affaire résolue",c.optString("solution")));else a.addButton(body,"Proposer un verdict",()->verdict(a,r,c,0,new int[3]));}
static void document(MainActivity a,JSONObject row,JSONObject c,int n)throws Exception{HashSet<Integer> read=indices(row,"_read");read.add(n);put(row,"_read",read);a.save();JSONArray doc=c.optJSONArray("docs").optJSONArray(n);TextView text=new TextView(a);text.setText(doc.optString(1));text.setTextSize(18);text.setTextIsSelectable(true);text.setPadding(a.dp(18),a.dp(12),a.dp(18),a.dp(12));ScrollView scroll=new ScrollView(a);scroll.addView(text);HashSet<Integer> pins=indices(row,"_pins");new AlertDialog.Builder(a).setTitle(doc.optString(0)).setView(scroll).setPositiveButton("Fermer",(d,w)->a.detail("affaires",row)).setNeutralButton(pins.contains(n)?"Désépingler":"Épingler",(d,w)->a.attempt(()->{if(pins.contains(n))pins.remove(n);else pins.add(n);put(row,"_pins",pins);a.save();a.detail("affaires",row);})).show();}
static void verdict(MainActivity a,JSONObject row,JSONObject c,int step,int[] answers){String[] keys={"suspects","proofs","places"},titles={"Qui a pris l’objet ?","Quel recoupement est décisif ?","Où chercher l’objet ?"};JSONArray choices=c.optJSONArray(keys[step]);String[] labels=new String[choices.length()];for(int i=0;i<labels.length;i++)labels[i]=choices.optString(i);new AlertDialog.Builder(a).setTitle(titles[step]).setItems(labels,(d,n)->{answers[step]=n;if(step<2)verdict(a,row,c,step+1,answers);else a.attempt(()->{JSONArray expected=c.optJSONArray("answer");boolean ok=true;for(int j=0;j<3;j++)if(answers[j]!=expected.optInt(j))ok=false;row.put("_attempts",row.optInt("_attempts")+1);if(ok){row.put("_solved",true);row.put("_points",Math.max(20,110-row.optInt("_attempts")*10));a.save();a.info("Affaire résolue · "+row.optInt("_points")+" points",c.optString("solution"));}else{a.save();a.info("Le dossier ne confirme pas ce verdict","Au moins un élément de ta conclusion ne correspond pas aux pièces. Recoupe accès, horaires et emplacement. Tu peux reprendre l’enquête.");}a.detail("affaires",row);});}).setNegativeButton("Annuler",null).show();}
}
